{"hypotheses": [
  {
    "name": "Hypothesis 1",
    "mechanism": "Momentum and value factors together can exploit firm's growth prospects and discounting effect better than individually.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "Mom12m"},
        {"weight": -0.5, "primitive": "BM"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Hypothesis 2",
    "mechanism": "Combining indicators of governance quality and earnings can help identify undervalued companies with strong earnings prospects.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "Governance"},
        {"weight": 0.5, "primitive": "EP"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Hypothesis 3",
    "mechanism": "Companies with high asset growth and low price to sales ratio are more likely to generate higher returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": -0.5, "primitive": "SP"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Hypothesis 4",
    "mechanism": "A strategy combining high earnings consistency with high operating profitability will generate returns by identifying companies with strong fundamentals.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "EarningsConsistency"},
        {"weight": 0.5, "primitive": "OperProf"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Hypothesis 5",
    "mechanism": "Firms with high short interest and low return on assets are more likely to underperform.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShortInterest"},
        {"weight": -1.0, "primitive": "NOA"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "ShortInterest", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Hypothesis 6",
    "mechanism": "Firms with high idiosyncratic volatility and low book to market are more likely to generate higher returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IdioVolAHT"},
        {"weight": -0.5, "primitive": "BM"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "weaker"},
      {"type": "international", "region": "emerging", "direction": "opposite_sign"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Hypothesis 7",
    "mechanism": "Firms with high leverage and low asset growth are more likely to underperform.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Leverage"},
        {"weight": -1.0, "primitive": "AssetGrowth"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "Leverage", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Hypothesis 8",
    "mechanism": "Firms with high earnings forecast dispersion and low price are more likely to underperform.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": -1.0, "primitive": "Price"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": null
  }
]}
